#!/usr/bin/env node
"use strict";

/**
 * One-time importer for JSON generated by scripts/export-appscript-data.gs.
 * Run with Application Default Credentials from an authorized admin machine.
 *
 * Example:
 *   npm install firebase-admin
 *   GOOGLE_CLOUD_PROJECT=monitoring-ict-smpit node scripts/import-firestore.js ./legacy-export.json
 *
 * The input file contains legacy passwords and private student data. Keep it
 * outside the repository, do not print its contents, and delete it securely
 * after import verification. This script is idempotent for keyed records.
 */

const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const { initializeApp, applicationDefault, getApps } = require("firebase-admin/app");
const { getAuth } = require("firebase-admin/auth");
const { getFirestore, FieldValue } = require("firebase-admin/firestore");

const PROJECT_ID = process.env.GOOGLE_CLOUD_PROJECT || process.env.GCLOUD_PROJECT || "monitoring-ict-smpit";
const SHEETS = [
  "siswa", "guru", "bab", "materi", "progres_materi", "tugas_mingguan",
  "progres_tugas_mingguan", "karya", "link_karya", "skl", "skl_sub",
  "jadwal", "pengaturan", "kurikulum", "prestasi", "tim", "rank_challenge"
];
const KEY_FIELDS = {
  siswa: ["kode_siswa"], guru: ["id_guru"], bab: ["id_bab"], materi: ["id_materi"],
  progres_materi: ["kode_siswa", "id_materi"], tugas_mingguan: ["id_tugas"],
  progres_tugas_mingguan: ["kode_siswa", "id_tugas"], karya: ["id_karya"],
  link_karya: ["id_link"], skl: ["id_skl"], skl_sub: ["id_sub"],
  jadwal: ["kelas", "hari", "waktu"], pengaturan: ["key"], kurikulum: ["judul"],
  prestasi: ["judul"], tim: ["nama"], rank_challenge: ["id_rank"]
};

function norm(value) {
  return String(value == null ? "" : value).trim();
}
function normCode(value) {
  return norm(value).toUpperCase();
}
function alias(role, id) {
  const slug = normCode(id).toLowerCase().replace(/[^a-z0-9._-]/g, "-");
  return role + "-" + slug + "@accounts.ict.alfirdaus.sch.id";
}
function safeDocId(sheet, row, index) {
  const fields = KEY_FIELDS[sheet] || [];
  const values = fields.map((key) => norm(row[key]));
  const keyed = fields.length > 0 && values.every(Boolean);
  const seed = keyed ? JSON.stringify([sheet, values]) : JSON.stringify([sheet, index, row]);
  return crypto.createHash("sha256").update(seed).digest("hex").slice(0, 40);
}
function cleanRecord(row) {
  const output = { ...row };
  delete output.password;
  delete output.password_hash;
  delete output.pin;
  delete output.pinHash;
  delete output.salt;
  return output;
}
function csvCell(value) {
  const s = String(value == null ? "" : value);
  return '"' + s.replace(/"/g, '""') + '"';
}
function randomPassword() {
  return crypto.randomBytes(12).toString("base64url") + "A7!";
}
function pinHash(pin, salt) {
  return crypto.scryptSync(pin, salt, 64).toString("hex");
}

async function ensureAccount(auth, role, id, displayName, oldPassword, report) {
  const normalized = normCode(id);
  if (!normalized) return;
  const email = alias(role, normalized);
  try {
    const existing = await auth.getUserByEmail(email);
    const previous = existing.customClaims || {};
    await auth.setCustomUserClaims(existing.uid, {
      ...previous,
      role: role,
      ...(role === "student" ? { studentCode: normalized } : { teacherId: normalized })
    });
    return;
  } catch (error) {
    if (error.code !== "auth/user-not-found") throw error;
  }

  const sourcePassword = norm(oldPassword);
  const shouldReset = sourcePassword.length < 6;
  const password = shouldReset ? randomPassword() : sourcePassword;
  const user = await auth.createUser({
    email: email,
    password: password,
    displayName: norm(displayName) || normalized,
    disabled: false
  });
  await auth.setCustomUserClaims(user.uid, {
    role: role,
    ...(role === "student" ? { studentCode: normalized } : { teacherId: normalized }),
    mustChangePassword: shouldReset || sourcePassword === "123456" || sourcePassword.length < 10
  });
  if (shouldReset) report.push({ role: role, id: normalized, email: email, temporaryPassword: password });
}

async function main() {
  const inputPath = process.argv[2];
  if (!inputPath || !fs.existsSync(inputPath)) {
    console.error("Pemakaian: node scripts/import-firestore.js <path-export-json>");
    process.exitCode = 2;
    return;
  }
  const payload = JSON.parse(fs.readFileSync(path.resolve(inputPath), "utf8"));
  if (payload.format !== "official-ict-appscript-export-v1" || !payload.sheets) {
    throw new Error("Format ekspor tidak dikenal. Jangan jalankan impor terhadap file sembarang.");
  }
  if (!getApps().length) initializeApp({ credential: applicationDefault(), projectId: PROJECT_ID });
  const db = getFirestore();
  const auth = getAuth();
  const accountResetReport = [];
  const parentInviteReport = [];
  const counts = {};

  for (const sheet of SHEETS) {
    const rows = Array.isArray(payload.sheets[sheet]) ? payload.sheets[sheet] : [];
    counts[sheet] = rows.length;
    for (let offset = 0; offset < rows.length; offset += 400) {
      const batch = db.batch();
      rows.slice(offset, offset + 400).forEach((row, i) => {
        const docId = safeDocId(sheet, row, offset + i);
        batch.set(db.collection("legacyData").doc(sheet).collection("rows").doc(docId), {
          record: cleanRecord(row),
          migratedAt: FieldValue.serverTimestamp(),
          source: "appscript"
        }, { merge: true });
      });
      await batch.commit();
    }
    console.log("Imported sheet:", sheet, "rows:", rows.length);
  }

  const students = payload.sheets.siswa || [];
  for (const student of students) {
    const code = normCode(student.kode_siswa);
    if (!code) continue;
    await ensureAccount(auth, "student", code, student.nama_siswa, student.password, accountResetReport);
    const accessRef = db.collection("parentAccess").doc(code);
    const accessSnap = await accessRef.get();
    if (!accessSnap.exists) {
      const pin = String(crypto.randomInt(100000, 1000000));
      const salt = crypto.randomBytes(16).toString("hex");
      await accessRef.set({
        studentCode: code,
        salt: salt,
        pinHash: pinHash(pin, salt),
        failedAttempts: 0,
        lockedUntilMs: 0,
        createdAt: FieldValue.serverTimestamp()
      });
      parentInviteReport.push({ kode_siswa: code, nama_siswa: student.nama_siswa || "", nama_ortu: student.nama_ortu || "", pin_orangtua: pin });
    }
  }
  for (const teacher of (payload.sheets.guru || [])) {
    await ensureAccount(auth, "teacher", teacher.id_guru, teacher.nama_guru, teacher.password, accountResetReport);
  }

  if (parentInviteReport.length) {
    const columns = ["kode_siswa", "nama_siswa", "nama_ortu", "pin_orangtua"];
    const csv = [columns.map(csvCell).join(",")].concat(parentInviteReport.map((row) => columns.map((key) => csvCell(row[key])).join(","))).join("\n");
    fs.writeFileSync("parent-invites.csv", csv, { mode: 0o600 });
    console.log("Private parent invite CSV created: parent-invites.csv");
  }
  if (accountResetReport.length) {
    const columns = ["role", "id", "email", "temporaryPassword"];
    const csv = [columns.map(csvCell).join(",")].concat(accountResetReport.map((row) => columns.map((key) => csvCell(row[key])).join(","))).join("\n");
    fs.writeFileSync("account-reset.csv", csv, { mode: 0o600 });
    console.warn("Some accounts needed temporary passwords. A private file account-reset.csv was created.");
  }
  fs.writeFileSync("migration-report.json", JSON.stringify({
    projectId: PROJECT_ID,
    exportedAt: payload.exportedAt || null,
    importedAt: new Date().toISOString(),
    counts: counts
  }, null, 2), { mode: 0o600 });
  console.log("Import completed. Counts only:", JSON.stringify(counts));
  console.log("Verify collections and test all role login paths before switching any live portal.");
}

main().catch((error) => {
  console.error("Migration failed:", error.message);
  process.exitCode = 1;
});
